def record_events(store, events: list[dict]) -> int:
    new_events = []
    seen = set(store.event_ids)
    for event in events:
        if not event.get("event_id") or not event.get("actor_id"):
            raise ValueError("each audit event requires event_id and actor_id")
        event_id = event["event_id"]
        if event_id not in seen:
            seen.add(event_id)
            new_events.append(event)
    if new_events:
        store.insert_events(new_events)
    return len(new_events)
